-- Generated by scripts/generate-fresh-knowledge-from-matrix.mjs from docs/FRESH_WEB_LITE_MASTER_MATRIX.csv.
-- Idempotent. Teaches Fresh AI the master matrix with no outside AI involved.
with m(n, category, module, purpose, phase, priority, status, notes) as (values
 (1,'Ecosystem','Core Foundation','Identity, auth, profiles, search, nav, notifications, settings, privacy, sync','P0-P1','Critical','IN PROGRESS','Platform layer'),
 (2,'Ecosystem','Fresh Intelligence','AI, Ara6, twin, memory, agents, knowledge, trust, opportunity','P0-P2','Critical','IN PROGRESS','Continuous'),
 (3,'Ecosystem','Fresh Flow / Digital Life','Shorts, long, posts, live, creator feeds, discovery','P0-P1','Critical','IN PROGRESS','Immersive Shorts path'),
 (4,'Ecosystem','Communication','Messaging, voice, video, groups, channels','P1-P2','High','PLANNED',''),
 (5,'Ecosystem','Creation','Studio, AI create, publish, collab','P0-P2','High','IN PROGRESS','CreateIntent'),
 (6,'Ecosystem','Learning & Growth','Academy, tutors, courses, skills','P2-P3','High','PLANNED',''),
 (7,'Ecosystem','Discovery','Universal search, ranking, recommendations','P1-P2','High','PLANNED',''),
 (8,'Ecosystem','Work','Jobs, projects, teams, AE workspace','P2-P3','High','PLANNED',''),
