 (10,'Ecosystem','Financial','Payments, transfers, wallet, invoicing','P0-P3','Critical','IN PROGRESS','Chrome live'),
 (11,'Ecosystem','Fresh Crypto','Assets, transfers, Web3 economics','P3-P4','High','PLANNED',''),
 (12,'Ecosystem','Digital Life Services','Travel, food, local, maps','P4','Medium','PLANNED',''),
 (13,'Ecosystem','Community','Groups, forums, reputation','P1-P2','High','PLANNED',''),
 (14,'Ecosystem','Business','CRM, marketing, analytics, agents','P3-P4','High','PLANNED',''),
 (15,'Ecosystem','Fresh Software / Ara6','Apps, APIs, extensions, adaptive UI','P2-P4','Critical','PLANNED',''),
 (16,'Ecosystem','Autonomous Engineering','Propose→test→owner approval→merge→deploy','P2-P4','Critical','PLANNED','Approval-gated'),
 (17,'Ecosystem','Creator Economy','Gifts, tips, memberships, earnings','P0-P2','High','IN PROGRESS','Gifts path'),
 (18,'Ecosystem','Premium','Premium AI, advanced tools','P3-P4','Medium','PLANNED',''),
 (19,'Ecosystem','Adults-Only Creator','Age-gated, compliance','P4','Medium','PLANNED',''),
 (20,'Ecosystem','Entertainment','Gaming, streaming, events','P3-P4','Medium','PLANNED',''),
 (21,'Ecosystem','Opportunity','Careers, funding, partnerships','P3','High','PLANNED',''),
 (22,'Cross-cutting','Security & Trust','Encryption, RLS, fraud, moderation','Every','Critical','IN PROGRESS','Continuous'),
 (23,'Cross-cutting','Design System','UI language, a11y, responsive','P0+','Critical','IN PROGRESS',''),
 (24,'Cross-cutting','Engineering / CI / Infra','Standards, Actions, Vercel, Supabase','Continuous','Critical','IN PROGRESS','Must stay green'),
 (25,'Cross-cutting','Business Revenue + Marketing','Monetization, growth','P2-P4','High','PLANNED',''),
 (26,'Cross-cutting','Owner Intelligence','Founder KPIs, health, revenue','Continuous','Critical','PLANNED',''),
 (27,'Cross-cutting','Legal & Ops','ToS, privacy, support, incidents','P1+','Critical','PLANNED',''),
 (28,'Cross-cutting','Innovation Backlog','Future ideas triage','Continuous','Medium','PLANNED',''),
 (29,'Architecture','Platform layers','Experience→…→Infrastructure','P0','Critical','PLANNED',''),
 (30,'Architecture','Canonical Data Model','Shared entities + ownership','P0','Critical','PLANNED',''),
 (31,'Architecture','Fresh ID','One identity foundation','P0','Critical','IN PROGRESS',''),
 (32,'Architecture','TRUEMODE','Truth decision boundary','P1','Critical','IN PROGRESS',''),
 (33,'Architecture','AI Governance','Agent permissions + AE workflow','P0','Critical','IN PROGRESS',''),
 (34,'Architecture','API & Events','Versioned contracts','P1','Critical','PLANNED',''),
 (35,'Architecture','Persistence rules','Source-of-truth map','P0','Critical','PLANNED',''),
 (36,'Architecture','Security architecture','Platform security + privacy','Every','Critical','IN PROGRESS',''),
 (37,'Architecture','DR & Reliability','RPO/RTO rollback','P2','Critical','PLANNED',''),
 (38,'Architecture','Observability','Logs, metrics, traces, audit','P1','Critical','PLANNED',''),
 (39,'Architecture','Production Gates G0-G11','Mandatory release path','Every','Critical','IN PROGRESS',''),
 (40,'Architecture','Definition of Done','Feature complete checklist','Every','Critical','LIVE VERIFIED','Documented'),
 (41,'Control','Control Plane','Platform coordination layer','P1','Critical','PLANNED',''),
 (42,'Control','Source-of-Truth Registry','Canonical domain owners','P1','Critical','PLANNED',''),
 (43,'Control','Authorization & Policy Engine','Shared authz primitive','P1','Critical','PLANNED',''),
 (44,'Control','Trust Graph','Claim→evidence→decision','P1','Critical','PLANNED',''),
 (45,'Control','AI Safety Boundary','Execution lifecycle','P0','Critical','IN PROGRESS',''),
 (46,'Control','Event & State','Events + state machines','P1','High','PLANNED',''),
 (47,'Control','Idempotency & Consistency','Retry-safe critical ops','P0','Critical','PLANNED',''),
 (48,'Control','Threat Modeling','Proactive abuse resistance','Every','Critical','PLANNED',''),
 (49,'Control','Data Lifecycle','CREATE→DELETE/EXPORT','P1','Critical','PLANNED',''),
 (50,'Control','Release & Feature Flags','Controlled rollout + kill switch','P1','Critical','PLANNED',''),
 (51,'Control','Provider Governance','Dependencies + fallbacks','P2','High','PLANNED',''),
 (52,'Control','Capacity & Cost','Performance + cost governance','P2','High','PLANNED',''),
 (53,'Control','18 Platform Invariants','Non-negotiable rules','Every','Critical','LIVE VERIFIED','Locked'),
 (54,'Control','Implementation Ledger','Evidence-based status','Every','Critical','IN PROGRESS',''),
 (55,'Control','Architecture Acceptance Test','Completion checklist','P4','Critical','PLANNED',''),
 (56,'Infra','Supabase','Canonical DB, auth, storage','P0','Critical','IN PROGRESS',''),
 (57,'Infra','Vercel','Production hosting','P0','Critical','IN PROGRESS','Must READY'),
 (58,'Infra','GitHub Actions','CI gates','P0','Critical','IN PROGRESS','Must green')
), s as (
  select m.*,
    case status when 'IN PROGRESS' then 'in progress: partly built and not yet complete'
                when 'PLANNED' then 'planned and not built yet'
                when 'LIVE VERIFIED' then 'live and verified'
                else lower(status) end as status_text,
    case status when 'IN PROGRESS' then 'Partly. ' || module || ' is in progress and not complete yet.'
                when 'PLANNED' then 'No. ' || module || ' is planned and not built yet.'
                when 'LIVE VERIFIED' then 'Yes. ' || module || ' is live and verified.'
                else module || ' status: ' || lower(status) || '.' end as availability
  from m
), k as (
  insert into public.fresh_ai_knowledge (user_id, project_id, title, content, modality, source, provenance, truth_state, confidence, metadata)
  select null, 'fresh-web-lite-platform', 'Master matrix: ' || module,
    module || ': ' || purpose || '. Category: ' || category || '. Phase ' || phase || '. Priority ' || priority || '. Status: ' || status_text || '.'
      || case when coalesce(notes, '') <> '' then ' Notes: ' || notes || '.' else '' end,
    'text', 'docs/FRESH_WEB_LITE_MASTER_MATRIX.csv', jsonb_build_object('kind', 'first-party', 'matrix_row', n), 'KNOWN', 0.9,
    jsonb_build_object('dataset', 'master-matrix-v1', 'status', status)
  from s
  where not exists (select 1 from public.fresh_ai_knowledge x where x.project_id = 'fresh-web-lite-platform' and x.user_id is null and x.title = 'Master matrix: ' || s.module)
  returning 1
)
insert into public.fresh_ai_training_examples (example_type, input_text, output_text, labels, source, quality_score, safety_score, dataset_version)
select 'instruction-response', t.input, t.output, jsonb_build_object('domain', 'master-matrix', 'module', s.module), 'first-party-platform-docs', 0.9, 1.0, 'master-matrix-v1'
from s cross join lateral (values
  ('What is ' || s.module || '?', s.module || ': ' || s.purpose || '. It is ' || s.status_text || '.'),
  ('Is ' || s.module || ' available today?', s.availability)
) as t(input, output)
where not exists (select 1 from public.fresh_ai_training_examples e where e.dataset_version = 'master-matrix-v1' and e.input_text = t.input);
